L44_1.m_fTalkTime = 0.03
L45_1 = "\227\129\173\227\129\136\227\129\173\227\129\136\232\166\139\227\129\159\239\188\159 \232\166\139\227\129\159\239\189\158\239\188\159\227\128\128\227\129\147\227\130\140\227\129\167\227\130\130\227\129\134\227\131\129\227\131\167\227\130\179\227\131\159\227\131\179\227\131\136\227\129\174\229\129\137\229\164\167\227\129\149\227\129\140\227\130\143\227\129\139\227\129\163\227\129\159\227\130\136\227\129\173\239\188\159\227\128\128\227\131\169\227\130\166\227\131\169\227\128\130"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You see? You see? Do you see the greatness of mint chocolate now, Laura?"
