L45_1 = "\231\156\139\229\136\176\230\178\146\230\156\137\239\188\129\239\188\129\231\159\165\233\129\147\232\150\132\232\141\183\229\183\167\229\133\139\229\138\155\231\154\132\229\142\178\229\174\179\228\186\134\229\144\167\239\188\140\232\152\191\230\139\137\239\188\159"
L44_1.m_Talk_TWN = L45_1
L45_1 = "\224\184\132\224\184\184\224\184\147\224\185\128\224\184\171\224\185\135\224\184\153\224\185\132\224\184\171\224\184\161? \224\184\132\224\184\184\224\184\147\224\185\128\224\184\171\224\185\135\224\184\153\224\185\132\224\184\171\224\184\161? \224\184\149\224\184\173\224\184\153\224\184\153\224\184\181\224\185\137\224\184\132\224\184\184\224\184\147\224\185\128\224\184\171\224\185\135\224\184\153\224\184\132\224\184\167\224\184\178\224\184\161\224\184\162\224\184\180\224\185\136\224\184\135\224\185\131\224\184\171\224\184\141\224\185\136\224\184\130\224\184\173\224\184\135\224\184\138\224\185\135\224\184\173\224\184\129\224\185\130\224\184\129\224\185\129\224\184\165\224\184\149\224\184\161\224\184\180\224\185\137\224\184\153\224\184\149\224\185\140\224\185\129\224\184\165\224\185\137\224\184\167\224\184\171\224\184\163\224\184\183\224\184\173\224\184\162\224\184\177\224\184\135\224\184\165\224\184\173\224\184\163\224\185\136\224\184\178?"
L44_1.m_Talk_THA = L45_1
L45_1 = "C\195\180 th\225\186\165y kh\195\180ng? C\195\180 th\225\186\165y kh\195\180ng? B\195\162y gi\225\187\157 c\195\180 \196\145\195\163 th\225\186\165y s\225\187\177 tuy\225\187\135t v\225\187\157i c\225\187\167a s\195\180 c\195\180 la b\225\186\161c h\195\160 ch\198\176a, Laura?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "\231\156\139\229\136\176\228\186\134\229\144\167\239\188\159\231\156\139\229\136\176\230\178\161~\239\188\159\231\142\176\229\156\168\232\175\165\231\159\165\233\129\147\232\150\132\232\141\183\229\183\167\229\133\139\229\138\155\231\154\132\228\188\159\229\164\167\228\185\139\229\164\132\228\186\134\229\144\167\239\188\140\229\138\179\230\139\137\239\188\159"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Siehst du? Siehst du, siehst du? Verstehst du jetzt, wie erhaben Minzschoko ist, Laura?"
